from collections import deque
class Solution:
    def minimumOperations(self, nums: List[int], pre: List[int]) -> int:
        start = tuple(nums)
        target = tuple(sorted(nums))
        if start == target:
            return 0
        q = deque([start])
        seen = {start}
        depth = 0
        while q:
            depth += 1
            for _ in range(len(q)):
                cur = list(q.popleft())
                for x in pre:
                    nxt = tuple(cur[:x][::-1] + cur[x:])
                    if nxt == target:
                        return depth
                    if nxt not in seen:
                        seen.add(nxt)
                        q.append(nxt)
        return -1

