class Solution {
public:
    int minimumOperations(vector<int>& nums, vector<int>& pre) {
        vector<int> target = nums;
        sort(target.begin(), target.end());
        if (nums == target) return 0;
        queue<vector<int>> q;
        set<vector<int>> seen;
        q.push(nums);
        seen.insert(nums);
        int depth = 0;
        while (!q.empty()) {
            depth++;
            int sz = q.size();
            while (sz--) {
                vector<int> cur = q.front(); q.pop();
                for (int x : pre) {
                    vector<int> nxt = cur;
                    reverse(nxt.begin(), nxt.begin() + x);
                    if (nxt == target) return depth;
                    if (!seen.count(nxt)) { seen.insert(nxt); q.push(nxt); }
                }
            }
        }
        return -1;
    }
};

