class Solution {
    public int minimumOperations(int[] nums, int[] pre) {
        int n = nums.length;
        String start = Arrays.toString(nums);
        int[] t = nums.clone();
        Arrays.sort(t);
        String target = Arrays.toString(t);
        if (start.equals(target)) return 0;
        Deque<String> q = new ArrayDeque<>();
        Set<String> seen = new HashSet<>();
        q.add(start); seen.add(start);
        int depth = 0;
        while (!q.isEmpty()) {
            depth++;
            for (int sz = q.size(); sz > 0; sz--) {
                int[] cur = parse(q.poll());
                for (int x : pre) {
                    int[] nxt = cur.clone();
                    for (int i = 0, j = x - 1; i < j; i++, j--) {
                        int tmp = nxt[i]; nxt[i] = nxt[j]; nxt[j] = tmp;
                    }
                    String s = Arrays.toString(nxt);
                    if (s.equals(target)) return depth;
                    if (seen.add(s)) q.add(s);
                }
            }
        }
        return -1;
    }
    private int[] parse(String s) {
        s = s.substring(1, s.length() - 1);
        String[] parts = s.split(", ");
        int[] a = new int[parts.length];
        for (int i = 0; i < parts.length; i++) a[i] = Integer.parseInt(parts[i]);
        return a;
    }
}

