var minimumOperations = function(nums, pre) {
    const key = a => a.join(',');
    const start = key(nums);
    const target = key([...nums].sort((a, b) => a - b));
    if (start === target) return 0;
    let q = [nums];
    const seen = new Set([start]);
    let depth = 0;
    while (q.length) {
        depth++;
        const nq = [];
        for (const cur of q) {
            for (const x of pre) {
                const nxt = cur.slice(0, x).reverse().concat(cur.slice(x));
                const k = key(nxt);
                if (k === target) return depth;
                if (!seen.has(k)) { seen.add(k); nq.push(nxt); }
            }
        }
        q = nq;
    }
    return -1;
};
